/** Matches the site's Australian positioning. */
export const DEFAULT_COUNTRY = 'au'

export const findCountry = (code) =>
  COUNTRIES.find((c) => c.code === code) ?? COUNTRIES.find((c) => c.code === DEFAULT_COUNTRY)

/**
 * E.164 allows at most 15 digits in total, country code included. The national
 * part is what is left — so the ceiling moves with the dial code and a 3-digit
 * prefix cannot smuggle an over-long number past a flat 15-digit check.
 */
export const nationalDigitRange = (dial) => ({
  min: Math.max(4, 7 - dial.length),
  max: 15 - dial.length,
})
